INSERT INTO exam_reports (grade, subject, exam_date, total, difficulty_level, scope, overview, sections, parent_guide)
VALUES (
  '초5', '수학',
  $q$2026. 7. 3.$q$,
  $q$24문항 (객관식 및 주관식 혼합 100%)$q$,
  $q$중상(中上)$q$,
  $q$분수, 다각형의 둘레와 넓이$q$,
  $q$이번 초등학교 5학년 2학기 기말고사는 '단순한 공식 암기를 넘어선 개념의 상호 연계 능력과 다단계 문장제 문제 해결 능력'을 평가하는 데 초점을 맞추었습니다. 5학년 수학은 중·고등 수학의 기초가 되는 '약수와 배수, 통분, 다각형의 넓이'가 본격적으로 융합되는 시기이므로 변별력 있는 문항들이 다수 배치되었습니다. 분수 파트에서는 단순 계산뿐만 아니라 조건에 맞는 기약분수의 개수를 구하거나 일정한 규칙성을 찾아내는 논리적 사고력이 요구되었습니다. 도형 파트에서는 기본적인 사각형의 넓이 공식 적용부터, 단위가 다른 차원(cm와 m)의 혼합 계산, 그리고 복잡하게 얽힌 다각형의 넓이를 쪼개거나 붙여서 해결하는 통합적 문제 해결 능력이 필요했습니다. 전체적인 난이도는 '중상(中上)' 수준이며, 정확한 연산력과 문제 독해력을 고루 갖춘 학생만이 고득점을 선점할 수 있도록 출제되었습니다.$q$,
  $j$[{"title": "출제 범위", "type": "list", "items": ["【분수 단원】 크기가 같은 분수 만들기, 분수의 통분 및 크기 비교, 기약분수 구하기, 분수의 덧셈과 뺄셈 (대분수 및 세 분수의 계산 포함)", "【다각형의 둘레와 넓이 단원】 정사각형·평행사변형·직사각형·마름모의 둘레와 넓이 구하기, 복잡한 다각형(L자형 등)의 둘레 및 넓이 응용"]}, {"title": "문항별 난이도 분석", "type": "difficulty", "rows": [{"level": "상", "color": "red", "items": "21, 22, 23, 24번", "desc": "조건 범위 내 만족하는 분모가 45인 기약분수 개수 구하기(21번) / 대각선 성질을 이용한 정사각형 확장 및 색칠된 넓이 구하기(22번) / 수열의 규칙을 파악하여 알맞은 기약분수 추론하기(23번) / 실생활 단위(갤런, 쿼트 등) 변환을 통한 최적의 가격 조건 도출 문장제(24번)"}, {"level": "중", "color": "yellow", "items": "7, 9, 13, 15, 17, 18, 19, 20번", "desc": "분수와 소수의 크기 비교 및 분모가 다른 대분수의 덧셈(7, 9번) / cm와 m 단위를 일치시켜 직사각형 넓이 구하기(13번) / 주어진 조건(둘레)을 활용해 두 정사각형의 한 변의 길이 차이 구하기(18번) / L자형 도형의 둘레 및 복합 다각형의 넓이 분할 계산(19, 20번)"}, {"level": "하", "color": "green", "items": "나머지 12개 문항", "desc": "크기가 같은 분수 만들기 및 공통분모 통분 기초(1, 2, 3, 5, 6번) / 삼각형의 높이 찾기 및 정다각형·평행사변형·마름모의 기본 둘레와 넓이 공식 적용(4, 11, 12, 14번)"}]}, {"title": "핵심 학습 포인트 및 향후 방향", "type": "keypoints", "items": [{"title": "연산 실수를 줄이는 '정확한 통분과 단위 환산 능력'", "desc": "단순히 분수의 덧·뺄셈 공식을 외우는 것을 넘어 분모가 다른 세 분수의 계산(10번)이나, cm와 m가 혼재된 넓이 계산(13번)처럼 사소한 변수를 스스로 통제할 수 있어야 합니다. 향후 분수의 곱셈과 나눗셈으로 확장될 때 치명적인 오답 요인이 되므로 철저한 단위 점검 습관이 필요합니다.", "num": "01"}, {"title": "도형을 분할하고 시각화하는 '공간적 문제 해결력'", "desc": "22번(정사각형 응용)이나 19, 20번(복잡한 다각형)처럼 정형화되지 않은 도형이 제시되었을 때, 보조선을 긋거나 아는 도형의 형태로 쪼개어 접근하는 훈련이 핵심이었습니다. 공식을 기계적으로 대입하는 버릇을 버리고 문제의 조건을 그림에 매칭하는 연습을 지속해야 합니다.", "num": "02"}]}]$j$::jsonb,
  $q$5학년 2학기 수학은 초등 수학 중 가장 고비가 되는 구간입니다. 현재 아이가 틀린 문항이 '단순한 공식 암기 부족(난이도 하)'의 문제인지, '조건이 누적된 문장제 독해 및 응용력 부족(난이도 상)' 때문인지 명확히 진단해야 합니다. 대치 프라임에서는 오답 노트를 활용하여, 복잡한 문장제 문제도 스스로 식을 세우고 논리 단계를 설명할 수 있을 때까지 1:1 밀착 관리를 진행하겠습니다.$q$
)
ON CONFLICT (grade, subject) DO UPDATE SET
  exam_date = EXCLUDED.exam_date,
